// src/utils/advisory-alerts/index.ts
var holidayAlertDaysAhead = 1;
var heatAlertThresholdC = 35;
var manilaOffsetMs = 8 * 3600000;
function manilaDate(now = new Date, daysAhead = 0) {
  return new Date(now.getTime() + manilaOffsetMs + daysAhead * 86400000).toISOString().slice(0, 10);
}
function holidayDueForAlert(holidays, now = new Date) {
  const target = manilaDate(now, holidayAlertDaysAhead);
  return holidays?.find((holiday) => holiday.date === target) ?? null;
}
function heatAlertFor(forecast, now = new Date) {
  const today = manilaDate(now);
  const hot = (forecast ?? []).filter((day) => day.date >= today && day.temperatureMaxC >= heatAlertThresholdC).sort((a, b) => a.date.localeCompare(b.date))[0];
  if (!hot)
    return null;
  const when = hot.date === today ? "today" : hot.date === manilaDate(now, 1) ? "tomorrow" : `on ${new Date(`${hot.date}T00:00:00Z`).toLocaleDateString("en-PH", { month: "long", day: "numeric", timeZone: "UTC" })}`;
  return { temperatureMaxC: Math.round(hot.temperatureMaxC), when };
}

// src/utils/advisory-http/index.ts
import { request as httpsRequest } from "https";
var configuredProxy = process.env.ADVISORY_HTTP_PROXY?.trim();
function requestDirect(url, signal) {
  const target = new URL(url);
  return new Promise((resolve, reject) => {
    const request = httpsRequest({
      hostname: target.hostname,
      port: target.port || 443,
      path: `${target.pathname}${target.search}`,
      method: "GET",
      headers: { accept: "application/json" }
    }, (response) => {
      const chunks = [];
      response.on("data", (chunk) => chunks.push(Buffer.from(chunk)));
      response.on("end", () => {
        const headers = new Headers;
        for (const [name, value] of Object.entries(response.headers)) {
          if (typeof value === "string")
            headers.set(name, value);
          else if (Array.isArray(value))
            headers.set(name, value.join(", "));
        }
        resolve(new Response(Buffer.concat(chunks), {
          status: response.statusCode ?? 502,
          headers
        }));
      });
    });
    const abort = () => request.destroy(new Error("advisory request aborted"));
    const cleanup = () => signal.removeEventListener("abort", abort);
    if (signal.aborted) {
      abort();
    } else {
      signal.addEventListener("abort", abort, { once: true });
    }
    request.on("error", (error) => {
      cleanup();
      reject(error);
    });
    request.on("close", cleanup);
    request.end();
  });
}
function fetchAdvisorySource(url, signal) {
  if (!configuredProxy && new URL(url).protocol === "https:") {
    return requestDirect(url, signal);
  }
  const init = {
    signal,
    headers: { accept: "application/json" },
    ...configuredProxy ? { proxy: configuredProxy } : {}
  };
  return fetch(url, init);
}

// src/modules/seller/services/seller.holidays.ts
var CACHE_TTL_MS = 60 * 60 * 1000;
var cache = new Map;
async function fetchPhilippineHolidays(year) {
  const cached = cache.get(year);
  if (cached && cached.expiresAt > Date.now())
    return cached.value;
  const controller = new AbortController;
  const timeout = setTimeout(() => controller.abort(), 4000);
  let value = null;
  try {
    const response = await fetchAdvisorySource(`https://date.nager.at/api/v3/PublicHolidays/${year}/PH`, controller.signal);
    if (!response.ok)
      throw new Error(`Nager.Date returned ${response.status}`);
    const payload = await response.json();
    if (!Array.isArray(payload))
      throw new Error("Nager.Date response was incomplete");
    const today = new Date().toISOString().slice(0, 10);
    const cutoff = new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
    const upcoming = payload.filter((holiday) => typeof holiday.date === "string" && typeof holiday.name === "string" && typeof holiday.localName === "string" && holiday.date >= today && holiday.date <= cutoff).map((holiday) => ({ date: holiday.date, name: holiday.name, localName: holiday.localName }));
    value = { available: true, upcoming };
  } catch (error) {
    console.warn("Philippine holiday source unavailable", error instanceof Error ? error.message : "request failed");
    value = null;
  } finally {
    clearTimeout(timeout);
  }
  if (value) {
    cache.set(year, { expiresAt: Date.now() + CACHE_TTL_MS, value });
  } else {
    cache.delete(year);
  }
  return value;
}

// src/modules/seller/services/seller.weather.ts
var CACHE_TTL_MS2 = 10 * 60 * 1000;
var cache2 = new Map;
function finiteNumber(value) {
  return typeof value === "number" && Number.isFinite(value);
}
async function fetchSellerWeather(latitude, longitude) {
  const key = `${latitude.toFixed(4)},${longitude.toFixed(4)}`;
  const cached = cache2.get(key);
  if (cached && cached.expiresAt > Date.now())
    return cached.value;
  const controller = new AbortController;
  const timeout = setTimeout(() => controller.abort(), 4000);
  let value = null;
  try {
    const query = new URLSearchParams({
      latitude: String(latitude),
      longitude: String(longitude),
      current: "temperature_2m,weather_code",
      daily: "weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max",
      forecast_days: "3",
      timezone: "auto"
    });
    const response = await fetchAdvisorySource(`https://api.open-meteo.com/v1/forecast?${query.toString()}`, controller.signal);
    if (!response.ok)
      throw new Error(`Open-Meteo returned ${response.status}`);
    const payload = await response.json();
    const daily = payload.daily;
    const arrays = [
      daily?.time,
      daily?.weather_code,
      daily?.temperature_2m_max,
      daily?.temperature_2m_min,
      daily?.precipitation_probability_max
    ];
    const requiredDays = 3;
    if (!payload.current || !arrays.every((items) => Array.isArray(items) && items.length >= requiredDays) || !finiteNumber(payload.current.temperature_2m) || !finiteNumber(payload.current.weather_code)) {
      throw new Error("Open-Meteo response was incomplete");
    }
    const [dates, codes, maximums, minimums, probabilities] = arrays;
    if (![...codes.slice(0, requiredDays), ...maximums.slice(0, requiredDays), ...minimums.slice(0, requiredDays), ...probabilities.slice(0, requiredDays)].every(finiteNumber)) {
      throw new Error("Open-Meteo response contained invalid values");
    }
    value = {
      available: true,
      current: {
        temperatureC: payload.current.temperature_2m,
        precipitationProbability: probabilities[0],
        weatherCode: payload.current.weather_code
      },
      forecast: dates.slice(0, 3).map((date, index) => ({
        date,
        temperatureMaxC: maximums[index],
        temperatureMinC: minimums[index],
        precipitationProbability: probabilities[index],
        weatherCode: codes[index]
      }))
    };
  } catch (error) {
    console.warn("Seller weather source unavailable", error instanceof Error ? error.message : "request failed");
    value = null;
  } finally {
    clearTimeout(timeout);
  }
  if (value) {
    cache2.set(key, { expiresAt: Date.now() + CACHE_TTL_MS2, value });
  } else {
    cache2.delete(key);
  }
  return value;
}

// src/modules/seller/services/seller.advisories.ts
var rainyCodes = new Set([51, 53, 55, 56, 57, 61, 63, 65, 66, 67, 80, 81, 82, 95, 96, 99]);
function createReminders(weather, holidays) {
  const reminders = [];
  if (weather) {
    const rainExpected = weather.forecast.some((day) => day.precipitationProbability >= 60 || rainyCodes.has(day.weatherCode));
    const heat = heatAlertFor(weather.forecast);
    if (rainExpected)
      reminders.push({ kind: "weather", message: "Rain is expected. Plan covered handling and inspect stored produce." });
    if (heat)
      reminders.push({ kind: "heat", message: `Heat alert: it may reach ${heat.temperatureMaxC}\xB0C ${heat.when}. Keep your produce in the shade and check it often.` });
  }
  const holiday = holidayDueForAlert(holidays?.upcoming);
  if (holiday)
    reminders.push({ kind: "holiday", message: `Tomorrow is ${holiday.name}. Check your pickup times and your stock.` });
  return reminders;
}
async function getSellerAdvisories(sellerId) {
  const context = await db.transaction(async (tx) => {
    await requireVerifiedSeller(tx, sellerId, false);
    await requireActiveUser(tx, sellerId, "seller");
    const [current] = await tx.select({ latitude: sellers_profile.latitude, longitude: sellers_profile.longitude }).from(sellers_profile).where(and(eq(sellers_profile.userId, sellerId), eq(sellers_profile.isCurrent, true))).limit(1);
    return { profile: current ?? null };
  });
  const profile = context.profile;
  const generatedAt = new Date().toISOString();
  if (!profile || profile.latitude === null || profile.longitude === null) {
    const holidayResult = await Promise.allSettled([
      fetchPhilippineHolidays(new Date().getUTCFullYear())
    ]);
    const holidays = holidayResult[0].status === "fulfilled" ? holidayResult[0].value : null;
    return {
      generatedAt,
      location: null,
      weather: null,
      holidays: holidays ?? { available: false, upcoming: [] },
      reminders: [
        { kind: "location", message: "Add a seller location to receive local weather advisories." },
        ...createReminders(null, holidays)
      ],
      sources: { weather: "unavailable", holidays: holidays ? "available" : "unavailable" }
    };
  }
  const [weatherResult, holidayResult] = await Promise.allSettled([
    fetchSellerWeather(profile.latitude, profile.longitude),
    fetchPhilippineHolidays(new Date().getUTCFullYear())
  ]);
  const weather = weatherResult.status === "fulfilled" ? weatherResult.value : null;
  const holidays = holidayResult.status === "fulfilled" ? holidayResult.value : null;
  return {
    generatedAt,
    location: { latitude: profile.latitude, longitude: profile.longitude },
    weather,
    holidays: holidays ?? { available: false, upcoming: [] },
    reminders: createReminders(weather, holidays),
    sources: {
      weather: weather ? "available" : "unavailable",
      holidays: holidays ? "available" : "unavailable"
    }
  };
}

// src/jobs/daily-advisory-summary.ts
function weatherWords(code) {
  if (code === 0 || code === 1)
    return "Sunny";
  if (code === 2)
    return "Partly cloudy";
  if (code === 3 || code === 45 || code === 48)
    return "Cloudy";
  if (code >= 51 && code <= 67)
    return "Rainy";
  if (code >= 80 && code <= 82)
    return "Showers";
  if (code >= 95)
    return "Thunderstorm";
  return "Fair";
}
function dayLabel(date) {
  return new Date(`${date}T00:00:00Z`).toLocaleDateString("en-PH", { month: "long", day: "numeric", timeZone: "UTC" });
}
function buildDailyAdvisorySummary(advisories) {
  const parts = [];
  const current = advisories.weather?.current;
  if (current) {
    parts.push(`Weather: ${weatherWords(current.weatherCode)}, ${Math.round(current.temperatureC)}\xB0C, ${Math.round(current.precipitationProbability)}% chance of rain.`);
  }
  const heat = heatAlertFor(advisories.weather?.forecast);
  if (heat)
    parts.push(`Heat alert: it may reach ${heat.temperatureMaxC}\xB0C ${heat.when}.`);
  const tomorrow = holidayDueForAlert(advisories.holidays.upcoming);
  const holiday = advisories.holidays.upcoming[0];
  if (tomorrow)
    parts.push(`Tomorrow is ${tomorrow.name}.`);
  else if (holiday)
    parts.push(`Next holiday: ${holiday.name} on ${dayLabel(holiday.date)}.`);
  return parts.join(" ");
}

// src/jobs/send-daily-advisory-notices.ts
var sendFromHour = 6;
var skippedToday = new Set;
async function sendDailyAdvisoryNotices(limit = 10) {
  const manila = new Date(Date.now() + 8 * 3600000);
  if (manila.getUTCHours() < sendFromHour)
    return { due: 0, sent: 0 };
  const day = manila.toISOString().slice(0, 10);
  for (const key of skippedToday)
    if (!key.endsWith(`:${day}`))
      skippedToday.delete(key);
  const due = await db.select({ sellerId: sellers_profile.userId }).from(sellers_profile).innerJoin(user, eq(user.id, sellers_profile.userId)).where(and(eq(sellers_profile.isCurrent, true), isNotNull(sellers_profile.latitude), isNotNull(sellers_profile.longitude), eq(user.isActive, true), sql`not exists (select 1 from seller_notifications n where n.dedupe_key = 'daily-advisory:' || ${sellers_profile.userId} || ':' || ${day}::text)`)).limit(100);
  let sent = 0;
  let tried = 0;
  for (const { sellerId } of due) {
    if (tried >= limit)
      break;
    const dedupeKey = `daily-advisory:${sellerId}:${day}`;
    if (skippedToday.has(dedupeKey))
      continue;
    tried++;
    try {
      const summary = buildDailyAdvisorySummary(await getSellerAdvisories(sellerId));
      if (!summary) {
        skippedToday.add(dedupeKey);
        continue;
      }
      await db.transaction((tx) => createSellerNotification(tx, { sellerId, kind: "daily_advisory", dedupeKey, payload: { summary } }));
      sent++;
    } catch (error) {
      skippedToday.add(dedupeKey);
      console.error("Daily advisory notice failed", { sellerId, error });
    }
  }
  return { due: due.length, sent };
}

// src/jobs/send-reservation-ending-notices.ts
var warningWindowMs = 30 * 60 * 1000;
async function sendReservationEndingNotices(limit = 100) {
  const now = new Date;
  const due = await db.select({ id: orders.id, sellerId: orders.sellersId }).from(orders).where(and(eq(orders.status, "pending"), gt(orders.expiresAt, now), sql`coalesce(${orders.pickupStart}, ${now.toISOString()}::timestamptz) <= ${now.toISOString()}::timestamptz`, lte(orders.expiresAt, new Date(now.getTime() + warningWindowMs)), sql`not exists (select 1 from ${seller_notifications} where ${seller_notifications.dedupeKey} = 'reservation-ending:' || ${orders.id}::text)`)).orderBy(asc(orders.expiresAt)).limit(limit);
  let created = 0;
  for (const order of due) {
    const row = await db.transaction((tx) => createSellerNotification(tx, {
      sellerId: order.sellerId,
      kind: "reservation_ending",
      dedupeKey: `reservation-ending:${order.id}`,
      orderId: order.id
    }));
    if (row)
      created++;
  }
  return created;
}

// src/utils/pickup/manila.ts
var MANILA_OFFSET_MS = 8 * 3600000;

// src/utils/pickup/qr-window.ts
var AUTO_CONFIRM_HOURS = 3;

// src/modules/pickup/services/pickup.order.confirm.ts
async function confirmOrderRow(tx, orderId, mode, sellerId) {
  const now = new Date;
  const [row] = await tx.update(orders).set({ confirmedAt: now, confirmationMode: mode, updatedAt: now }).where(and(eq(orders.id, orderId), eq(orders.status, "pending"), isNull(orders.confirmedAt), gt(orders.expiresAt, now), sellerId ? eq(orders.sellersId, sellerId) : undefined)).returning({ id: orders.id, buyersId: orders.buyersId, sellersId: orders.sellersId });
  if (!row)
    return null;
  await tx.insert(order_status_history).values({ orderId, status: "confirmed", actorId: mode === "manual" ? sellerId : null, note: mode === "auto" ? "Confirmed automatically after 3 hours" : "Confirmed by the seller" });
  await notifyBuyer(tx, {
    buyerId: row.buyersId,
    orderId,
    key: `order-confirmed:${orderId}`,
    message: mode === "auto" ? "The seller did not answer in 3 hours, so your order was confirmed automatically. You can no longer cancel it. Please come at your pickup time." : "The seller confirmed your order. You can no longer cancel it. Please come at your pickup time."
  });
  if (mode === "auto") {
    await notifySeller(tx, { sellerId: row.sellersId, orderId, key: `order-auto-confirmed:${orderId}`, message: "You did not confirm this order in 3 hours, so it was confirmed for you. Please prepare it for the pickup time." });
  }
  return row;
}

// src/modules/pickup/services/pickup.order.auto-confirm.ts
async function autoConfirmOrders(limit = 100) {
  const cutoff = new Date(Date.now() - AUTO_CONFIRM_HOURS * 3600000);
  const due = await db.select({ id: orders.id }).from(orders).where(and(eq(orders.status, "pending"), isNull(orders.confirmedAt), isNotNull(orders.pickupStart), lte(orders.createdAt, cutoff), gt(orders.expiresAt, new Date))).limit(limit);
  let confirmed = 0;
  for (const row of due) {
    if (await db.transaction((tx) => confirmOrderRow(tx, row.id, "auto")))
      confirmed++;
  }
  return confirmed;
}

// src/modules/pickup/services/pickup.decline.finalize.ts
var outcomeEvent = {
  seller_fault: { kind: "seller_decline_fault", who: "seller" },
  buyer_invalid: { kind: "buyer_invalid_decline", who: "buyer" },
  buyer_false_photo: { kind: "buyer_false_photo", who: "buyer" }
};
var outcomeText = {
  seller_fault: {
    buyer: "Your decline was accepted. You are not charged for the declined items. You get 0 trust points.",
    seller: "The decline was confirmed as your fault. It adds 2 trust points and counts in your fault rate. Take the produce back; it is not put back into stock. You can dispute this within 7 days."
  },
  buyer_invalid: {
    buyer: "Your decline was not valid, so it counts like a late cancellation and adds 1 point. You can dispute this within 7 days.",
    seller: "The decline was not valid. You get 0 points, and the produce went back into your stock so you can sell it again."
  },
  disputed: {
    buyer: "The seller disagreed with your decline. Nobody gets points. The order is closed as declined at pickup, and you are not charged for the declined items.",
    seller: "You disagreed with the decline. Nobody gets points. The order is closed as declined at pickup, and the produce is not put back into stock."
  },
  buyer_false_photo: {
    buyer: "The system found that this decline photo was already used on another decline. This adds 2 points, like confirmed bad conduct. You can dispute this within 7 days.",
    seller: "The system found that the buyer's photo was already used on another decline. You get 0 points, and the produce went back into your stock."
  }
};
async function finalizeDecline(tx, decline, outcome) {
  const now = new Date;
  await tx.update(order_declines).set({ status: outcome, decidedAt: now }).where(eq(order_declines.id, decline.id));
  const rows = await tx.select().from(ordered_items).where(eq(ordered_items.ordersId, decline.orderId));
  let total = 0;
  for (const row of rows) {
    const declined = decline.items.find((item) => item.itemId === row.id);
    const ordered = Number(row.quantity ?? 0);
    const remaining = declined ? Math.max(0, ordered - declined.quantity) : ordered;
    if (declined) {
      const subtotal = (remaining * Number(row.unitPrice)).toFixed(2);
      await tx.update(ordered_items).set({ quantity: remaining.toFixed(2), subtotal }).where(eq(ordered_items.id, row.id));
      if (outcome !== "seller_fault" && outcome !== "disputed") {
        await tx.update(sellers_product).set({ productQty: sql`${sellers_product.productQty} + ${declined.quantity.toFixed(2)}` }).where(eq(sellers_product.id, row.productId));
      }
    }
    total += remaining * Number(row.unitPrice);
  }
  await tx.update(orders).set({
    totalAmount: total.toFixed(2),
    updatedAt: now,
    ...decline.isFull ? { status: "declined", declinedAt: now } : {}
  }).where(eq(orders.id, decline.orderId));
  await tx.insert(order_status_history).values({ orderId: decline.orderId, status: decline.isFull ? "declined" : "partly_declined", actorId: null, note: outcome });
  await notifyBuyer(tx, { buyerId: decline.buyerId, orderId: decline.orderId, key: `decline-decided:${decline.id}`, message: outcomeText[outcome].buyer });
  await notifySeller(tx, { sellerId: decline.sellerId, orderId: decline.orderId, key: `decline-decided:${decline.id}`, message: outcomeText[outcome].seller, kind: "trust_decision" });
  if (outcome === "disputed")
    return null;
  const { kind, who } = outcomeEvent[outcome];
  const subjectId = who === "seller" ? decline.sellerId : decline.buyerId;
  const eventKey = `decline:${decline.orderId}`;
  await recordTrustEvent(tx, { eventKey, orderId: decline.orderId, subjectId, kind, classification: "verified", sourceId: decline.id, reason: outcome });
  return { subjectId, eventKey, kind };
}

// src/modules/pickup/services/pickup.decline.auto-accept.ts
async function autoAcceptDeclines(limit = 100) {
  const due = await db.select({ id: order_declines.id }).from(order_declines).where(and(eq(order_declines.status, "pending_seller"), lte(order_declines.sellerDueAt, new Date))).limit(limit);
  let accepted = 0;
  for (const row of due) {
    const finalized = await db.transaction(async (tx) => {
      const [decline] = await tx.select().from(order_declines).where(eq(order_declines.id, row.id)).for("update").limit(1);
      if (!decline || decline.status !== "pending_seller")
        return null;
      await tx.update(order_declines).set({ sellerResponse: "auto_accepted", sellerRespondedAt: new Date }).where(eq(order_declines.id, decline.id));
      return finalizeDecline(tx, decline, "seller_fault");
    });
    if (!finalized)
      continue;
    accepted++;
    await evaluateTrustAction(finalized.subjectId, null, finalized.eventKey, finalized.kind);
  }
  return accepted;
}

// src/utils/pickup/no-show.ts
async function recordNoShow(tx, input) {
  const [prior] = await tx.select({ n: sql`count(*)::int` }).from(buyer_no_shows).where(and(eq(buyer_no_shows.buyerId, input.buyerId), eq(buyer_no_shows.excused, false)));
  const sequence = Number(prior?.n ?? 0) + 1;
  const weight = 2;
  const [row] = await tx.insert(buyer_no_shows).values({ orderId: input.orderId, buyerId: input.buyerId, markedBy: input.markedBy, sequence, weight }).onConflictDoNothing({ target: buyer_no_shows.orderId }).returning();
  if (!row)
    return null;
  await tx.update(orders).set({ noShowAt: new Date }).where(eq(orders.id, input.orderId));
  const eventKey = `buyer-expired:${input.orderId}`;
  await recordTrustEvent(tx, {
    eventKey,
    orderId: input.orderId,
    subjectId: input.buyerId,
    kind: "buyer_failed_reservation",
    classification: "verified",
    sourceId: input.orderId,
    weight,
    reason: "Missed pickup"
  });
  return { eventKey, sequence, weight };
}

// src/modules/pickup/services/pickup.order.no-show.auto.ts
var SELLER_MARK_WINDOW_MS = 3600000;
async function recordUnmarkedNoShows(limit = 100) {
  const due = await db.select({ id: orders.id, buyerId: orders.buyersId }).from(orders).where(and(eq(orders.status, "expired"), isNotNull(orders.pickupStart), isNull(orders.noShowAt), lte(orders.expiredAt, new Date(Date.now() - SELLER_MARK_WINDOW_MS)), notExists(db.select({ one: order_declines.id }).from(order_declines).where(eq(order_declines.orderId, orders.id))))).limit(limit);
  let recorded = 0;
  for (const row of due) {
    const outcome = await db.transaction((tx) => recordNoShow(tx, { orderId: row.id, buyerId: row.buyerId, markedBy: "system" }));
    if (!outcome)
      continue;
    recorded++;
    await evaluateTrustAction(row.buyerId, row.id, outcome.eventKey, "buyer_failed_reservation");
  }
  return recorded;
}

// src/utils/trust/recalculate.ts
async function recalculateTrustStanding(subjectId, why = "Your score fell") {
  if (!trustActionPolicy.enabled)
    return { revoked: 0 };
  const standing = await readTrustStanding(subjectId);
  await syncSellerFlags(standing);
  const active = await readActiveActions(subjectId);
  const above = active.filter((row) => !row.actionKey.includes("inactivity") && levelRank(actionLevel(row)) > levelRank(standing.level));
  if (!above.length)
    return { revoked: 0 };
  const now = new Date;
  await db.transaction(async (tx) => {
    await tx.update(trust_actions).set({ revokedAt: now, revocationReason: `${why}, so this level no longer applies.` }).where(inArray(trust_actions.id, above.map((row) => row.id)));
    if (above.some((row) => actionLevel(row) === "block")) {
      await tx.update(user).set({ isActive: true }).where(eq(user.id, subjectId));
    }
    await queueTrustNotice(tx, {
      noticeKey: `trust-recalc:${subjectId}:${now.getTime()}`,
      recipientId: subjectId,
      kind: "trust_level_lowered",
      detail: `${why}. Your score is now ${standing.score} and your level is ${levelLabel[standing.level]}. The earlier restriction has ended.`
    });
  });
  return { revoked: above.length };
}
async function recalculateActiveStandings(limit = 100) {
  const rows = await db.selectDistinct({ subjectId: trust_actions.subjectId }).from(trust_actions).where(and(isNull(trust_actions.revokedAt), notLike(trust_actions.actionKey, "%inactivity%"), sql`${trust_actions.level} is not null`)).limit(limit);
  let revoked = 0;
  for (const row of rows)
    revoked += (await recalculateTrustStanding(row.subjectId, "Old points faded")).revoked;
  return revoked;
}

// src/jobs/run-scheduled.ts
async function runScheduledJobs() {
  const autoConfirmed = await autoConfirmOrders();
  const expiredOrders = await expirePendingOrders();
  const noShowsRecorded = await recordUnmarkedNoShows();
  const declinesAccepted = await autoAcceptDeclines();
  const awayEnded = await closeExpiredAway();
  const standingsLowered = await recalculateActiveStandings();
  const reservationEndingNotices = await sendReservationEndingNotices();
  const userInactivity = await checkUserInactivity();
  const inquiriesProcessed = await processInquiryDeadlines();
  const noticesSent = await sendPendingTrustNotices();
  const trustRestrictionsExpired = await expireTrustRestrictions();
  const sellerListingNotices = await sendSellerListingNotices();
  const rankedBoost = await queueRankedBoost();
  const sellerVisibilityBoosts = await deliverSellerVisibilityBoosts();
  const sellerBoostFollowUps = await deliverSellerBoostFollowUps();
  const priceDropSetupNotices = await sendPriceDropSetupNotices();
  const dailyAdvisoryNotices = await sendDailyAdvisoryNotices();
  const pushNotifications = await deliverPushNotifications();
  return { autoConfirmed, expiredOrders, noShowsRecorded, declinesAccepted, awayEnded, standingsLowered, reservationEndingNotices, userInactivity, inquiriesProcessed, noticesSent, trustRestrictionsExpired, sellerListingNotices, rankedBoost, sellerVisibilityBoosts, sellerBoostFollowUps, priceDropSetupNotices, dailyAdvisoryNotices, pushNotifications };
}

// src/worker.ts
var running = false;
var stopping = false;
async function tick() {
  if (running)
    return;
  running = true;
  try {
    const result = await runScheduledJobs();
    console.log("Scheduled jobs completed", result);
  } catch (error) {
    console.error("Scheduled jobs failed", error);
  } finally {
    running = false;
  }
}
tick();
var timer = setInterval(() => void tick(), 60000);
async function stop() {
  if (stopping)
    return;
  stopping = true;
  clearInterval(timer);
  while (running)
    await new Promise((resolve) => setTimeout(resolve, 100));
  process.exit(0);
}
process.on("SIGINT", stop);
process.on("SIGTERM", stop);
